<?php require '../config.php';$students=$pdo->query('SELECT id,name,course FROM students ORDER BY id')->fetchAll();$xml=new SimpleXMLElement('<?xml version="1.0" encoding="UTF-8"?><students/>');foreach($students as $s){$st=$xml->addChild('student');$st->addChild('id',(string)$s['id']);$st->addChild('name',htmlspecialchars($s['name'],ENT_XML1));$st->addChild('course',htmlspecialchars($s['course'],ENT_XML1));}$path=__DIR__.'/students_export.xml';$xml->asXML($path);?><h1>Export MySQL students to XML</h1><p>Export complete. <?=count($students)?> student(s) written to <code>tasks/students_export.xml</code>.</p><a href="students_export.xml">Open XML file</a><br><a href="../index.php">Home</a>